select 
from ${tableName}
where enterprise_code = #{enterpriseCode}
and delete_flag = false

    and batch_number LIKE '%'|| #{batchNumber} ||'%'


    AND deliver_date >= #{deliverDatePre}


    AND deliver_date <= #{deliverDatePost}


    AND business_belong = #{businessBelong}

order by deliver_date ASC, create_time DESC

